#!/usr/bin/env python3
"""
gen_compare_sql.py: generate T-SQL that proves a candidate table holds the same data
as a baseline table. Use it for golden-master tests when legacy SQL is modernized.

What the generated script checks (SQL Server 2016+ and Fabric SQL database):
  1. columns present in only one table (schema drift)
  2. row counts
  3. rows only in the baseline / only in the candidate (EXCEPT both ways)
  4. duplicate keys on each side (EXCEPT hides duplicates, so this is checked separately)
  5. per-column difference counts on rows matched by key
  6. sample rows of each difference, then an overall PASS/FAIL

Usage:
  python gen_compare_sql.py --baseline baseline.UM00300 --candidate gold.UM00300_Connections \
      --key LocationID,ServiceType,EquipmentID --exclude DEX_ROW_ID,RowId,LoadMessage \
      --where "TakeId = 'go-live'" --sample 20 > compare_UM00300.sql
  sqlcmd -S <server> -d <database> -i compare_UM00300.sql

Exclude columns that legitimately differ between runs: identity values (DEX_ROW_ID),
timestamps and run IDs. Comparisons use the database collation, which is the same
semantics CSM uses (trailing spaces ignored; usually case-insensitive).
"""
from __future__ import annotations

import argparse
import re
import sys
from datetime import datetime, timezone

NAME_RX = re.compile(r"^\[?[A-Za-z_][\w$#@ ]*\]?\.\[?[A-Za-z_][\w$#@ ]*\]?$")


def qualified(name: str) -> str:
    if not NAME_RX.match(name):
        sys.exit(f"table name must be schema.table, got {name!r}")
    schema, table = [p.strip("[]") for p in name.split(".", 1)]
    return f"[{schema.replace(']', ']]')}].[{table.replace(']', ']]')}]"


def qcol(col: str) -> str:
    col = col.strip().strip("[]")
    if not col:
        sys.exit("empty column name")
    return f"[{col.replace(']', ']]')}]"


def lit(s: str) -> str:
    return "N'" + s.replace("'", "''") + "'"


def build(baseline, candidate, keys, exclude, where, sample, no_throw=False) -> str:
    b, c = qualified(baseline), qualified(candidate)
    keys = [k.strip().strip("[]") for k in keys if k.strip()]
    if not keys:
        sys.exit("--key needs at least one column")
    excl = [e.strip().strip("[]") for e in exclude if e.strip()]
    excl_list = ", ".join(lit(e) for e in excl) or "N''"
    excl_keys_list = ", ".join(lit(e) for e in excl + keys)
    key_cols = ", ".join(qcol(k) for k in keys)
    key_join = " AND ".join(f"b.{qcol(k)} = k.{qcol(k)}" for k in keys)
    key_join_sql = key_join.replace("'", "''")
    where_sql = where.strip() or "1 = 1"
    stamp = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")

    return f"""/* Golden-master comparison generated by gen_compare_sql.py on {stamp}
   baseline : {b}
   candidate: {c}
   key      : {', '.join(keys)}
   excluded : {', '.join(excl) or '(none)'}
   filter   : {where_sql}
*/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;    -- required by the XML methods used to build column lists (legacy sqlcmd defaults to OFF)
GO
SET NOCOUNT ON;
DECLARE @b nvarchar(400) = {lit(b)}, @c nvarchar(400) = {lit(c)};
DECLARE @where nvarchar(max) = {lit(where_sql)};
DECLARE @cols nvarchar(max), @diff nvarchar(max), @sql nvarchar(max);
DECLARE @nb bigint, @nc bigint, @ob bigint, @oc bigint, @db bigint, @dc bigint;
DECLARE @result TABLE (check_name nvarchar(200), baseline bigint NULL, candidate bigint NULL, status varchar(10));

IF OBJECT_ID(@b) IS NULL OR OBJECT_ID(@c) IS NULL
    THROW 50010, 'Baseline or candidate table not found.', 1;

/* 1. Schema drift: columns present in only one table */
SELECT 'only_in_baseline_schema' AS drift, bc.name AS column_name
FROM sys.columns AS bc
WHERE bc.object_id = OBJECT_ID(@b) AND bc.name NOT IN ({excl_list})
  AND NOT EXISTS (SELECT 1 FROM sys.columns AS cc WHERE cc.object_id = OBJECT_ID(@c) AND cc.name = bc.name)
UNION ALL
SELECT 'only_in_candidate_schema', cc.name
FROM sys.columns AS cc
WHERE cc.object_id = OBJECT_ID(@c) AND cc.name NOT IN ({excl_list})
  AND NOT EXISTS (SELECT 1 FROM sys.columns AS bc WHERE bc.object_id = OBJECT_ID(@b) AND bc.name = cc.name);

SELECT @cols = STUFF((
    SELECT N', ' + QUOTENAME(bc.name)
    FROM sys.columns AS bc
    JOIN sys.columns AS cc ON cc.object_id = OBJECT_ID(@c) AND cc.name = bc.name
    WHERE bc.object_id = OBJECT_ID(@b) AND bc.name NOT IN ({excl_list})
    ORDER BY bc.column_id
    FOR XML PATH(''), TYPE).value('.', 'nvarchar(max)'), 1, 2, N'');
IF @cols IS NULL
    THROW 50011, 'No comparable columns: check the table names and exclusions.', 1;

/* 2. Row counts */
SET @sql = N'SELECT @nb = COUNT_BIG(*) FROM ' + @b + N' WHERE ' + @where + N';'
         + N'SELECT @nc = COUNT_BIG(*) FROM ' + @c + N' WHERE ' + @where + N';';
EXEC sys.sp_executesql @sql, N'@nb bigint OUTPUT, @nc bigint OUTPUT', @nb = @nb OUTPUT, @nc = @nc OUTPUT;
INSERT @result VALUES (N'row_count', @nb, @nc, CASE WHEN @nb = @nc THEN 'PASS' ELSE 'FAIL' END);

/* 3. Rows only on one side */
SET @sql = N'SELECT @ob = COUNT_BIG(*) FROM (SELECT ' + @cols + N' FROM ' + @b + N' WHERE ' + @where
         + N' EXCEPT SELECT ' + @cols + N' FROM ' + @c + N' WHERE ' + @where + N') AS d;'
         + N'SELECT @oc = COUNT_BIG(*) FROM (SELECT ' + @cols + N' FROM ' + @c + N' WHERE ' + @where
         + N' EXCEPT SELECT ' + @cols + N' FROM ' + @b + N' WHERE ' + @where + N') AS d;';
EXEC sys.sp_executesql @sql, N'@ob bigint OUTPUT, @oc bigint OUTPUT', @ob = @ob OUTPUT, @oc = @oc OUTPUT;
INSERT @result VALUES (N'rows_only_in_baseline', @ob, NULL, CASE WHEN @ob = 0 THEN 'PASS' ELSE 'FAIL' END);
INSERT @result VALUES (N'rows_only_in_candidate', NULL, @oc, CASE WHEN @oc = 0 THEN 'PASS' ELSE 'FAIL' END);

/* 4. Duplicate keys (EXCEPT collapses duplicates, so count them explicitly) */
SET @sql = N'SELECT @db = COUNT_BIG(*) FROM (SELECT {key_cols} FROM ' + @b + N' WHERE ' + @where
         + N' GROUP BY {key_cols} HAVING COUNT(*) > 1) AS d;'
         + N'SELECT @dc = COUNT_BIG(*) FROM (SELECT {key_cols} FROM ' + @c + N' WHERE ' + @where
         + N' GROUP BY {key_cols} HAVING COUNT(*) > 1) AS d;';
EXEC sys.sp_executesql @sql, N'@db bigint OUTPUT, @dc bigint OUTPUT', @db = @db OUTPUT, @dc = @dc OUTPUT;
INSERT @result VALUES (N'duplicate_keys', @db, @dc, CASE WHEN @db = @dc THEN 'PASS' ELSE 'FAIL' END);

/* 5. Per-column differences on rows matched by key (NULL-safe) */
SELECT @diff = STUFF((
    SELECT N' UNION ALL SELECT N''' + REPLACE(bc.name, '''', '''''') + N''' AS column_name, '
         + N'SUM(CASE WHEN b.' + QUOTENAME(bc.name) + N' = k.' + QUOTENAME(bc.name)
         + N' OR (b.' + QUOTENAME(bc.name) + N' IS NULL AND k.' + QUOTENAME(bc.name) + N' IS NULL) THEN 0 ELSE 1 END)'
         + N' AS rows_different FROM (SELECT * FROM ' + @b + N' WHERE ' + @where
         + N') AS b JOIN (SELECT * FROM ' + @c + N' WHERE ' + @where + N') AS k ON {key_join_sql}'
    FROM sys.columns AS bc
    JOIN sys.columns AS cc ON cc.object_id = OBJECT_ID(@c) AND cc.name = bc.name
    WHERE bc.object_id = OBJECT_ID(@b) AND bc.name NOT IN ({excl_keys_list})
    ORDER BY bc.column_id
    FOR XML PATH(''), TYPE).value('.', 'nvarchar(max)'), 1, 11, N'');
IF @diff IS NOT NULL
BEGIN
    SET @sql = N'SELECT column_name, rows_different FROM (' + @diff + N') AS x WHERE rows_different > 0 ORDER BY rows_different DESC;';
    EXEC sys.sp_executesql @sql;
END;

/* 6. Samples of each difference */
SET @sql = N'SELECT TOP ({int(sample)}) ''baseline_only'' AS side, d.* FROM (SELECT ' + @cols + N' FROM ' + @b + N' WHERE ' + @where
         + N' EXCEPT SELECT ' + @cols + N' FROM ' + @c + N' WHERE ' + @where + N') AS d;'
         + N'SELECT TOP ({int(sample)}) ''candidate_only'' AS side, d.* FROM (SELECT ' + @cols + N' FROM ' + @c + N' WHERE ' + @where
         + N' EXCEPT SELECT ' + @cols + N' FROM ' + @b + N' WHERE ' + @where + N') AS d;';
EXEC sys.sp_executesql @sql;

SELECT check_name, baseline, candidate, status FROM @result;
SELECT CASE WHEN EXISTS (SELECT 1 FROM @result WHERE status = 'FAIL') THEN 'FAIL' ELSE 'PASS' END AS overall;
{"" if no_throw else "IF EXISTS (SELECT 1 FROM @result WHERE status = 'FAIL') THROW 50020, 'Golden-master comparison failed. See the results above.', 1;"}
"""


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--baseline", required=True, help="schema.table holding the legacy output")
    ap.add_argument("--candidate", required=True, help="schema.table holding the new output")
    ap.add_argument("--key", required=True, help="comma-separated natural key columns")
    ap.add_argument("--exclude", default="", help="comma-separated columns to ignore")
    ap.add_argument("--where", default="", help="filter applied to both tables, e.g. TakeId = 'go-live'")
    ap.add_argument("--sample", type=int, default=20)
    ap.add_argument("--no-throw", action="store_true",
                    help="don't raise an error at the end when a check fails (by default it does, so sqlcmd -b fails CI)")
    ap.add_argument("-o", "--out", help="write to a file instead of stdout")
    a = ap.parse_args(argv)
    sql = build(a.baseline, a.candidate, a.key.split(","), a.exclude.split(","), a.where, a.sample, a.no_throw)
    if a.out:
        with open(a.out, "w", encoding="utf-8") as fh:
            fh.write(sql)
    else:
        sys.stdout.write(sql)
    return 0


if __name__ == "__main__":
    sys.exit(main())
